#pragma once
#include "weather.hpp"
#include <map>
namespace locations {
inline std::string extractZip(std::string s){size_t a=s.find_first_not_of(" \t\r\n");if(a==std::string::npos)return "";s=s.substr(a);size_t b=s.find_last_not_of(" \t\r\n");s=s.substr(0,b+1);if(s.size()<5||!validZip(s.substr(0,5)))return "";if(s.size()>5&&(s.size()<9||s.substr(5,3)!=" - "))return "";return s.substr(0,5);}
inline bool acceptPreview(unsigned request,unsigned active,const std::string&code,const std::string&input){return request==active&&code==extractZip(input);}
inline std::string menuText(const std::string&s){std::string out;for(char c:s){out+=c;if(c=='&')out+='&';}return out;}
inline std::string fullState(const std::string&code){static const std::map<std::string,std::string> names={
{"AL","Alabama"},{"AK","Alaska"},{"AZ","Arizona"},{"AR","Arkansas"},{"CA","California"},{"CO","Colorado"},{"CT","Connecticut"},{"DE","Delaware"},{"DC","District of Columbia"},{"FL","Florida"},{"GA","Georgia"},{"HI","Hawaii"},{"ID","Idaho"},{"IL","Illinois"},{"IN","Indiana"},{"IA","Iowa"},{"KS","Kansas"},{"KY","Kentucky"},{"LA","Louisiana"},{"ME","Maine"},{"MD","Maryland"},{"MA","Massachusetts"},{"MI","Michigan"},{"MN","Minnesota"},{"MS","Mississippi"},{"MO","Missouri"},{"MT","Montana"},{"NE","Nebraska"},{"NV","Nevada"},{"NH","New Hampshire"},{"NJ","New Jersey"},{"NM","New Mexico"},{"NY","New York"},{"NC","North Carolina"},{"ND","North Dakota"},{"OH","Ohio"},{"OK","Oklahoma"},{"OR","Oregon"},{"PA","Pennsylvania"},{"RI","Rhode Island"},{"SC","South Carolina"},{"SD","South Dakota"},{"TN","Tennessee"},{"TX","Texas"},{"UT","Utah"},{"VT","Vermont"},{"VA","Virginia"},{"WA","Washington"},{"WV","West Virginia"},{"WI","Wisconsin"},{"WY","Wyoming"},{"PR","Puerto Rico"},{"VI","US Virgin Islands"},{"GU","Guam"},{"AS","American Samoa"},{"MP","Northern Mariana Islands"}};auto it=names.find(code);return it==names.end()?code:it->second;}
inline bool valid(const json& j){for(auto k:{"zip","city","state","country"})if(!j.contains(k)||!j[k].is_string()||j[k].get<std::string>().empty()||j[k].get<std::string>().size()>256)return false;return validZip(j["zip"].get<std::string>())&&(!j.contains("state_code")||j["state_code"].is_string());}
inline bool coordinates(const json&j){if(!valid(j)||!j.contains("latitude")||!j.contains("longitude")||!j["latitude"].is_number()||!j["longitude"].is_number())return false;double a=j["latitude"].get<double>(),b=j["longitude"].get<double>();return std::isfinite(a)&&std::isfinite(b)&&fabs(a)<=90&&fabs(b)<=180;}
inline json parse(const std::string&code,const json& response){auto p=response.at("places").at(0);std::string state=p.value("state",std::string());std::string shortState=p.value("state abbreviation",std::string());if(state.empty())state=fullState(shortState);
 json j={{"zip",code},{"city",p.at("place name")},{"state",state},{"state_code",shortState},{"country",response.value("country",std::string("United States"))},{"latitude",std::stod(p.at("latitude").get<std::string>())},{"longitude",std::stod(p.at("longitude").get<std::string>())}};if(!coordinates(j))throw std::runtime_error("Location service returned incomplete or invalid data.");return j;}
inline json fromWeather(const json&w){if(!w.is_object()||!w.contains("zip")||!w["zip"].is_string())return json();std::string code=w["zip"].get<std::string>(),state=w.value("state_name",fullState(w.value("state",std::string())));json j={{"zip",code},{"city",w.value("city",std::string())},{"state",state},{"state_code",w.value("state",std::string())},{"country",w.value("country",std::string("United States"))}};return valid(j)?j:json();}
inline std::string label(const json&j){return valid(j)?j.at("zip").get<std::string>()+" - "+j.at("city").get<std::string>()+", "+j.at("state").get<std::string>()+", "+j.at("country").get<std::string>():std::string();}
inline json sanitize(const json&raw){json out=json::object();if(!raw.is_object())return out;for(auto it=raw.begin();it!=raw.end();++it)if(valid(it.value())&&it.key()==it.value()["zip"].get<std::string>())out[it.key()]=it.value();return out;}
}
